/*
 * Implementation of the inotify syscalls: `inotify_init`, `inotify_init1`, `inotify_add_watch`
 * and `inotify_rm_watch`, plus the event-generation side called by the filesystem paths.
 *
 * The watch table and the per-instance event queues live entirely in the LibOS; events are
 * generated by *this LibOS's own operations* (the hooks are called from the syscall paths that
 * touch dentries), so another process's changes are not notified — the documented limitation
 * (decision 4 of the topic's PLAN.md). Like eventfd/timerfd, an instance keeps a dummy host
 * eventfd only so that blocking `read()` and poll/epoll get wake-ups; the queue state in the LibOS
 * decides what poll actually reports (`post_poll` in `fs/inotify/fs.c`).
 *
 * Locking: `g_inotify_lock` (spinlock) guards the global watch list and the instance count;
 * `info.inotify.lock` (spinlock) guards one instance's queue; order is always global -> instance.
 * `put_dentry()` is legal outside `g_dcache_lock` (established pattern, e.g. `sys/libos_stat.c`),
 * so watch removal needs no dcache lock. `PalStreamWrite` on the notification eventfd never runs
 * under a spinlock: deliveries collect what to notify and signal it after unlocking.
 */

#include "libos_fs.h"
#include "libos_handle.h"
#include "libos_inotify.h"
#include "libos_internal.h"
#include "libos_signal.h"
#include "libos_table.h"
#include "libos_utils.h"
#include "stat.h"

/* the kernel's defaults from /proc/sys/fs/inotify (exposed through procfs, see `fs/proc/fs.c`) */
#define INOTIFY_DEF_MAX_QUEUED_EVENTS 16384
#define INOTIFY_MAX_WATCHES           8192

unsigned int libos_inotify_max_queued_events(void) {
    return INOTIFY_DEF_MAX_QUEUED_EVENTS;
}

unsigned int libos_inotify_max_user_watches(void) {
    return INOTIFY_MAX_WATCHES;
}

/* the bits `inotify_add_watch()` accepts (kernel: fs/notify/inotify/inotify_user.c) */
#define INOTIFY_WATCH_VALID (IN_ALL_EVENTS | IN_EXCL_UNLINK | IN_MASK_CREATE | IN_MASK_ADD | \
                             IN_ONESHOT | IN_ONLYDIR | IN_DONTFOLLOW)

static spinlock_t g_inotify_lock = INIT_SPINLOCK_UNLOCKED;
static struct libos_inotify_watch* g_inotify_watches; /* protected by `g_inotify_lock` */
static unsigned int g_inotify_instances;              /* under the same lock */

/* Smallest free wd of `group` (the kernel's IDR does the same; LTP `inotify06` asserts reuse).
 * Called with `g_inotify_lock` held. */
static int alloc_wd_locked(struct libos_handle* group) {
    for (int wd = 0; ; wd++) {
        bool used = false;
        for (struct libos_inotify_watch* w = g_inotify_watches; w; w = w->next) {
            if (w->group == group && w->wd == wd) {
                used = true;
                break;
            }
        }
        if (!used)
            return wd;
    }
}

/* Append an event to an instance's queue (no locks assumed held beyond `g_inotify_lock` possibly
 * being held by the caller — only the instance spinlock is taken here). `*out_notify` asks the
 * caller to signal the host eventfd *after* unlocking. */
static void inotify_queue_event(struct libos_handle* group, int wd, unsigned int mask,
                                unsigned int cookie, const char* name, unsigned int name_len,
                                bool* out_notify) {
    size_t name_bytes = name ? name_len : 0;
    struct libos_inotify_event* ev = malloc(sizeof(*ev) + name_bytes);
    if (!ev) {
        if (out_notify)
            *out_notify = false;
        return;
    }
    ev->wd = wd;
    ev->mask = mask;
    ev->cookie = cookie;
    ev->len = name_bytes;
    if (name_bytes)
        memcpy(ev->name, name, name_bytes);
    ev->next = NULL;

    bool notify = false;
    spinlock_lock(&group->info.inotify.lock);
    struct libos_inotify_handle* n = &group->info.inotify;
    /* the kernel coalesces a new event identical to the last queued one (same wd, mask, cookie,
     * name) instead of queueing it (inotify_add_to_queue; LTP `inotify02` relies on this) */
    if (n->ev_tail && n->ev_tail->wd == wd && n->ev_tail->mask == mask &&
        n->ev_tail->cookie == cookie && n->ev_tail->len == name_bytes &&
        (name_bytes == 0 || memcmp(n->ev_tail->name, name, name_bytes) == 0)) {
        spinlock_unlock(&group->info.inotify.lock);
        free(ev);
        if (out_notify)
            *out_notify = false;
        return;
    }
    if (n->queued >= n->queue_limit) {
        /* kernel: drop the event and keep exactly one IN_Q_OVERFLOW at the queue's tail */
        bool has_overflow = n->ev_tail && n->ev_tail->mask == IN_Q_OVERFLOW;
        if (!has_overflow) {
            free(ev);
            ev = calloc(1, sizeof(*ev));
            if (!ev) {
                spinlock_unlock(&group->info.inotify.lock);
                if (out_notify)
                    *out_notify = false;
                return;
            }
            ev->wd = -1;
            ev->mask = IN_Q_OVERFLOW;
            if (n->ev_tail)
                n->ev_tail->next = ev;
            else
                n->ev_head = ev;
            n->ev_tail = ev;
            n->queued++;
            notify = true;
        }
        spinlock_unlock(&group->info.inotify.lock);
        if (out_notify)
            *out_notify = notify;
        return;
    }
    if (n->ev_tail)
        n->ev_tail->next = ev;
    else
        n->ev_head = ev;
    n->ev_tail = ev;
    n->queued++;
    if (n->queued == 1) {
        /* empty -> nonempty: one host notification, drained when the queue empties */
        n->dummy_host_val++;
        notify = true;
    }
    spinlock_unlock(&group->info.inotify.lock);
    if (out_notify)
        *out_notify = notify;
}

static void inotify_notify_host(struct libos_handle* group) {
    uint64_t one = 1;
    size_t size = sizeof(one);
    int ret = PalStreamWrite(group->pal_handle, /*offset=*/0, &size, &one);
    if (ret < 0)
        log_debug("inotify: failed to write the host notification: %s", pal_strerror(ret));
}

/* A collected delivery: queue this on the group after unlocking (the name is already padded and
 * NUL-terminated inside `name`). */
struct inotify_delivery {
    struct inotify_delivery* next;
    struct libos_handle* group; /* referenced for the post-unlock notification */
    int wd;
    unsigned int mask;
    unsigned int cookie;
    char name[];
};

static void inotify_free_deliveries(struct inotify_delivery* list) {
    while (list) {
        struct inotify_delivery* next = list->next;
        put_handle(list->group);
        free(list);
        list = next;
    }
}

/*
 * Deliver `mask` (a single event bit) to the watches of `dir`. `name == NULL` means an event on
 * the watched object itself; `isdir` then adds `IN_ISDIR` (the kernel does add it for directory
 * self-events like `IN_ATTRIB`, and does not add it for `IN_DELETE_SELF`/`IN_MOVE_SELF`). A
 * non-NULL `name` (already padded) is a directory-level event reported with that name. `cookie`
 * links a MOVED_FROM/MOVED_TO pair. ONESHOT watches are removed as they fire.
 */
/*
 * dnotify (`fcntl(F_NOTIFY)`): a directory descriptor asks for a signal when the directory or an
 * entry in it changes. It reuses the inotify event points: every event delivered to a watched
 * directory dentry is also checked against the dnotify marks. The signal is the descriptor's
 * F_SETSIG signal with `si_fd`/`si_code = POLL_MSG` (or a plain SIGIO when none was set), queued
 * on this process (the kernel's `send_sigio()`). Marks are process-local and are dropped when
 * the descriptor is closed (`libos_dnotify_fd_closed()`).
 */
#define DN_ACCESS    0x00000001
#define DN_MODIFY    0x00000002
#define DN_CREATE    0x00000004
#define DN_DELETE    0x00000008
#define DN_RENAME    0x00000010
#define DN_ATTRIB    0x00000020
#define DN_MULTISHOT 0x80000000
#define LINUX_POLL_MSG 3 /* si_code of a SIGIO for a message (dnotify) */

struct dnotify_mark {
    struct dnotify_mark* next;
    struct libos_dentry* dir; /* holds a reference */
    struct libos_handle* hdl; /* not refcounted: the mark is dropped when the fd is closed */
    int fd;
    unsigned long mask;
};

static spinlock_t g_dnotify_lock = INIT_SPINLOCK_UNLOCKED;
static struct dnotify_mark* g_dnotify_marks; /* protected by `g_dnotify_lock` */

static unsigned long dnotify_mask_of(unsigned int in_mask) {
    unsigned long dn = 0;
    if (in_mask & IN_ACCESS)
        dn |= DN_ACCESS;
    if (in_mask & IN_MODIFY)
        dn |= DN_MODIFY;
    if (in_mask & IN_CREATE)
        dn |= DN_CREATE;
    if (in_mask & IN_DELETE)
        dn |= DN_DELETE;
    if (in_mask & (IN_MOVED_FROM | IN_MOVED_TO))
        dn |= DN_RENAME;
    if (in_mask & IN_ATTRIB)
        dn |= DN_ATTRIB;
    return dn;
}

int libos_dnotify_set(struct libos_handle* hdl, int fd, unsigned long arg) {
    if (!hdl->dentry || !hdl->inode || !S_ISDIR(hdl->inode->type))
        return -ENOTDIR;
    unsigned long mask = arg & (DN_ACCESS | DN_MODIFY | DN_CREATE | DN_DELETE | DN_RENAME |
                                DN_ATTRIB | DN_MULTISHOT);

    struct libos_dentry* drop = NULL;
    struct dnotify_mark* fresh = NULL;
    if (mask & ~DN_MULTISHOT) {
        fresh = malloc(sizeof(*fresh));
        if (!fresh)
            return -ENOMEM;
    }
    spinlock_lock(&g_dnotify_lock);
    struct dnotify_mark** pp = &g_dnotify_marks;
    while (*pp) {
        struct dnotify_mark* m = *pp;
        if (m->hdl == hdl && m->fd == fd) {
            /* one mark per descriptor: a new F_NOTIFY adds to its mask (DN_MULTISHOT stays, as
             * in the kernel's `attach_dn()`), 0 removes it */
            if (fresh) {
                m->mask |= mask;
                free(fresh);
                fresh = NULL;
                spinlock_unlock(&g_dnotify_lock);
                return 0;
            }
            *pp = m->next;
            drop = m->dir;
            free(m);
            break;
        }
        pp = &m->next;
    }
    if (fresh) {
        get_dentry(hdl->dentry);
        *fresh = (struct dnotify_mark){.next = g_dnotify_marks, .dir = hdl->dentry, .hdl = hdl,
                                       .fd = fd, .mask = mask};
        g_dnotify_marks = fresh;
    }
    spinlock_unlock(&g_dnotify_lock);
    if (drop)
        put_dentry(drop);
    return 0;
}

void libos_dnotify_fd_closed(int fd, struct libos_handle* hdl) {
    struct libos_dentry* drop[8];
    size_t ndrop = 0;
    spinlock_lock(&g_dnotify_lock);
    struct dnotify_mark** pp = &g_dnotify_marks;
    while (*pp) {
        struct dnotify_mark* m = *pp;
        if (m->fd == fd && m->hdl == hdl && ndrop < ARRAY_SIZE(drop)) {
            *pp = m->next;
            drop[ndrop++] = m->dir;
            free(m);
            continue;
        }
        pp = &m->next;
    }
    spinlock_unlock(&g_dnotify_lock);
    for (size_t i = 0; i < ndrop; i++)
        put_dentry(drop[i]);
}

static void dnotify_deliver(struct libos_dentry* dir, unsigned int in_mask) {
    unsigned long dn = dnotify_mask_of(in_mask);
    if (!dn || !g_dnotify_marks)
        return;
    struct {
        int fd;
        int sig;
    } sends[8];
    size_t nsend = 0;
    struct libos_dentry* drop[8];
    size_t ndrop = 0;

    spinlock_lock(&g_dnotify_lock);
    struct dnotify_mark** pp = &g_dnotify_marks;
    while (*pp) {
        struct dnotify_mark* m = *pp;
        if (m->dir != dir || !(m->mask & dn) || nsend >= ARRAY_SIZE(sends)) {
            pp = &m->next;
            continue;
        }
        sends[nsend].fd = m->fd;
        sends[nsend].sig = __atomic_load_n(&m->hdl->fown_signal, __ATOMIC_RELAXED);
        nsend++;
        if (!(m->mask & DN_MULTISHOT) && ndrop < ARRAY_SIZE(drop)) {
            /* a one-shot mark is gone after its first event */
            *pp = m->next;
            drop[ndrop++] = m->dir;
            free(m);
            continue;
        }
        pp = &m->next;
    }
    spinlock_unlock(&g_dnotify_lock);
    for (size_t i = 0; i < ndrop; i++)
        put_dentry(drop[i]);

    for (size_t i = 0; i < nsend; i++) {
        siginfo_t info = {0};
        if (sends[i].sig) {
            info.si_signo = sends[i].sig;
            info.si_code = LINUX_POLL_MSG;
            info.si_band = 0x0001 | 0x0040 | 0x0400; /* POLLIN | POLLRDNORM | POLLMSG */
            info.si_fd = sends[i].fd;
        } else {
            info.si_signo = SIGIO;
            info.si_code = SI_KERNEL;
        }
        append_signal(/*thread=*/NULL, &info);
        libos_signal_wake_waiters(info.si_signo);
    }
}

static void inotify_deliver(struct libos_dentry* dir, unsigned int mask, const char* name,
                            unsigned int name_len, bool isdir, unsigned int cookie) {
    dnotify_deliver(dir, mask);

    struct inotify_delivery* head = NULL;
    struct inotify_delivery* tail = NULL;
    struct libos_dentry* freed_dentry = NULL; /* ONESHOT removals: at most one dentry per event */

    spinlock_lock(&g_inotify_lock);
    struct libos_inotify_watch** pp = &g_inotify_watches;
    while (*pp) {
        struct libos_inotify_watch* w = *pp;
        if (w->dir_dentry != dir || !(w->mask & mask)) {
            pp = &w->next;
            continue;
        }

        size_t extra = name ? name_len : 0;
        struct inotify_delivery* d = malloc(sizeof(*d) + extra);
        if (!d) {
            pp = &w->next;
            continue;
        }
        d->group = w->group;
        get_handle(d->group);
        d->wd = w->wd;
        d->mask = mask | (isdir ? IN_ISDIR : 0);
        d->cookie = cookie;
        d->next = NULL;
        if (extra)
            memcpy(d->name, name, extra);
        if (tail)
            tail->next = d;
        else
            head = d;
        tail = d;

        if (w->oneshot) {
            *pp = w->next;
            spinlock_lock(&w->group->info.inotify.lock);
            w->group->info.inotify.watch_count--;
            spinlock_unlock(&w->group->info.inotify.lock);
            freed_dentry = w->dir_dentry;
            free(w);
            continue; /* `pp` already points at the next watch */
        }
        pp = &w->next;
    }
    spinlock_unlock(&g_inotify_lock);

    if (freed_dentry)
        put_dentry(freed_dentry);

    /* queue outside the global lock; notify only after that */
    for (struct inotify_delivery* d = head; d; d = d->next) {
        bool notify = false;
        inotify_queue_event(d->group, d->wd, d->mask, d->cookie, name ? d->name : NULL,
                            name ? name_len : 0, &notify);
        if (notify)
            inotify_notify_host(d->group);
    }
    inotify_free_deliveries(head);
}

void libos_inotify_file_event(struct libos_dentry* dent, unsigned int mask) {
    /*
     * The kernel's `fsnotify_file()` notifies the parent-directory watches (with the child's
     * name) first, then the watch on the object itself; both get `IN_ISDIR` when the object is a
     * directory (verified against this kernel: `chmod` of a watched directory yields
     * `IN_ATTRIB | IN_ISDIR`).
     */
    bool isdir = dent->inode && S_ISDIR(dent->inode->type);
    if (dent->parent) {
        size_t len = ALIGN_UP(strlen(dent->name) + 1, INOTIFY_NAME_ALIGN);
        inotify_deliver(dent->parent, mask, dent->name, len, isdir, /*cookie=*/0);
    }
    inotify_deliver(dent, mask, /*name=*/NULL, 0, isdir, /*cookie=*/0);
}

void libos_inotify_child_event(struct libos_dentry* dir, struct libos_dentry* child,
                               unsigned int mask, unsigned int cookie) {
    bool isdir = child->inode && S_ISDIR(child->inode->type);
    libos_inotify_child_event_raw(dir, child->name, mask, isdir, cookie);
}

void libos_inotify_child_event_raw(struct libos_dentry* dir, const char* name, unsigned int mask,
                                   bool isdir, unsigned int cookie) {
    size_t len = ALIGN_UP(strlen(name) + 1, INOTIFY_NAME_ALIGN);
    inotify_deliver(dir, mask, name, len, isdir, cookie);
}

/*
 * The kernel's sequence for removing a watched object (verified against this kernel):
 * unlinking a watched *file* first reports the link-count `IN_ATTRIB` on its own watch; then
 * `IN_DELETE_SELF` (never with `IN_ISDIR`, even for directories), every watch on the object is
 * dropped each with an `IN_IGNORED` behind it, and finally the parent-directory watch gets the
 * `IN_DELETE` (with name and `IN_ISDIR` when it was a directory) — the parent event comes last.
 */
void libos_inotify_delete_self_locked(struct libos_dentry* dent, bool report_delete_parent) {
    assert(locked(&g_dcache_lock));

    if (!S_ISDIR(dent->inode->type))
        inotify_deliver(dent, IN_ATTRIB, NULL, 0, false, 0); /* link count dropped to zero */

    inotify_deliver(dent, IN_DELETE_SELF, NULL, 0, /*isdir=*/false, 0);

    struct libos_handle* groups[8];
    size_t ngroups = 0;
    const size_t groups_max = sizeof(groups) / sizeof(groups[0]);

    spinlock_lock(&g_inotify_lock);
    struct libos_inotify_watch** pp = &g_inotify_watches;
    while (*pp) {
        struct libos_inotify_watch* w = *pp;
        if (w->dir_dentry == dent) {
            *pp = w->next;
            inotify_queue_event(w->group, w->wd, IN_IGNORED, 0, NULL, 0, /*notify=*/NULL);
            spinlock_lock(&w->group->info.inotify.lock);
            w->group->info.inotify.watch_count--;
            spinlock_unlock(&w->group->info.inotify.lock);
            if (ngroups < groups_max)
                groups[ngroups++] = w->group;
            struct libos_dentry* wd_ = w->dir_dentry;
            free(w);
            put_dentry(wd_);
            continue;
        }
        pp = &w->next;
    }
    spinlock_unlock(&g_inotify_lock);

    /* the instance keeps existing after an unlink (only close frees it), so these are safe to
     * signal now; more instances than the small array watch one dentry is a scenario without
     * practical callers — they simply get their (already queued) event on their next poll */
    for (size_t i = 0; i < ngroups; i++)
        inotify_notify_host(groups[i]);

    if (report_delete_parent && dent->parent)
        libos_inotify_child_event(dent->parent, dent, IN_DELETE, /*cookie=*/0);
}

void libos_inotify_move_self(struct libos_dentry* dent) {
    /* verified: the kernel's `IN_MOVE_SELF` carries no `IN_ISDIR`, even for directories */
    inotify_deliver(dent, IN_MOVE_SELF, NULL, 0, /*isdir=*/false, 0);
}

/*
 * The LibOS `rename` moves the inode between the two dentries (the kernel moves the dentry), so
 * the watches of the old dentry have to follow the inode to the new one — they must keep firing
 * for the object's new location (LTP `inotify02` unlinks a child of the renamed directory). Call
 * with `g_dcache_lock` held, after the rename succeeded.
 */
void libos_inotify_transfer_watches(struct libos_dentry* from, struct libos_dentry* to) {
    assert(locked(&g_dcache_lock));

    struct libos_dentry* put_after[8];
    size_t np = 0;

    spinlock_lock(&g_inotify_lock);
    for (struct libos_inotify_watch* w = g_inotify_watches; w; w = w->next) {
        if (w->dir_dentry != from)
            continue;
        get_dentry(to);
        w->dir_dentry = to;
        if (np < sizeof(put_after) / sizeof(put_after[0]))
            put_after[np++] = from;
    }
    spinlock_unlock(&g_inotify_lock);

    for (size_t i = 0; i < np; i++)
        put_dentry(put_after[i]);
}

void libos_inotify_swap_watches(struct libos_dentry* a, struct libos_dentry* b) {
    assert(locked(&g_dcache_lock));

    /* Each watch holds one reference on its dentry; both dentries are referenced by the caller,
     * so the counts can be moved without a dentry being freed in between. */
    spinlock_lock(&g_inotify_lock);
    for (struct libos_inotify_watch* w = g_inotify_watches; w; w = w->next) {
        if (w->dir_dentry == a) {
            get_dentry(b);
            put_dentry(a);
            w->dir_dentry = b;
        } else if (w->dir_dentry == b) {
            get_dentry(a);
            put_dentry(b);
            w->dir_dentry = a;
        }
    }
    spinlock_unlock(&g_inotify_lock);
}

/* drop all watches and queued events of a closing instance (kernel: `inotify_release`); the
 * kernel discards the still-queued events and emits no `IN_IGNORED` (nobody could read them) */
void libos_inotify_destroy_watches(struct libos_handle* group) {
    spinlock_lock(&g_inotify_lock);
    struct libos_inotify_watch** pp = &g_inotify_watches;
    while (*pp) {
        struct libos_inotify_watch* w = *pp;
        if (w->group == group) {
            *pp = w->next;
            put_dentry(w->dir_dentry);
            free(w);
            continue;
        }
        pp = &w->next;
    }
    g_inotify_instances--;
    spinlock_unlock(&g_inotify_lock);

    spinlock_lock(&group->info.inotify.lock);
    struct libos_inotify_event* ev = group->info.inotify.ev_head;
    while (ev) {
        struct libos_inotify_event* next = ev->next;
        free(ev);
        ev = next;
    }
    group->info.inotify.ev_head = NULL;
    group->info.inotify.ev_tail = NULL;
    group->info.inotify.queued = 0;
    spinlock_unlock(&group->info.inotify.lock);
}

long libos_syscall_inotify_init1(int flags) {
    if (flags & ~(IN_CLOEXEC | IN_NONBLOCK))
        return -EINVAL;

    spinlock_lock(&g_inotify_lock);
    if (g_inotify_instances >= INOTIFY_MAX_INSTANCES) {
        spinlock_unlock(&g_inotify_lock);
        return -ENFILE; /* the kernel's answer over max_user_instances */
    }
    g_inotify_instances++;
    spinlock_unlock(&g_inotify_lock);

    struct libos_handle* hdl = get_new_handle();
    if (!hdl) {
        spinlock_lock(&g_inotify_lock);
        g_inotify_instances--;
        spinlock_unlock(&g_inotify_lock);
        return -ENOMEM;
    }

    hdl->type = TYPE_INOTIFY;
    hdl->fs = &inotify_builtin_fs;
    hdl->flags = O_RDONLY | (flags & IN_NONBLOCK ? O_NONBLOCK : 0);
    hdl->acc_mode = MAY_READ;

    hdl->info.inotify.broken_in_child = false;
    hdl->info.inotify.ev_head = NULL;
    hdl->info.inotify.ev_tail = NULL;
    hdl->info.inotify.queued = 0;
    hdl->info.inotify.queue_limit = INOTIFY_DEF_MAX_QUEUED_EVENTS;
    hdl->info.inotify.watch_count = 0;
    hdl->info.inotify.dummy_host_val = 0;

    int ret = PalStreamOpen(URI_PREFIX_EVENTFD, PAL_ACCESS_RDWR, /*share_flags=*/0,
                            PAL_CREATE_IGNORED, /*flags=*/0, &hdl->pal_handle);
    if (ret < 0) {
        ret = pal_to_unix_errno(ret);
        goto out;
    }

    ret = set_new_fd_handle(hdl, flags & IN_CLOEXEC ? FD_CLOEXEC : 0, NULL);
out:
    if (ret < 0) {
        spinlock_lock(&g_inotify_lock);
        g_inotify_instances--;
        spinlock_unlock(&g_inotify_lock);
    }
    put_handle(hdl);
    return ret;
}

long libos_syscall_inotify_init(void) {
    return libos_syscall_inotify_init1(/*flags=*/0);
}

long libos_syscall_inotify_add_watch(int fd, char* pathname, unsigned int mask) {
    if (!pathname || !is_user_string_readable(pathname))
        return -EFAULT;

    /* the kernel: at least one event bit, and no bits outside the settable ones */
    if (!(mask & IN_ALL_EVENTS) || (mask & ~INOTIFY_WATCH_VALID))
        return -EINVAL;

    struct libos_handle* hdl = get_fd_handle(fd, NULL, NULL);
    if (!hdl)
        return -EBADF;
    if (hdl->type != TYPE_INOTIFY) {
        put_handle(hdl);
        return -EINVAL; /* the kernel checks the fd's fsnotify-group identity the same way */
    }
    if (!(hdl->acc_mode & MAY_READ)) {
        put_handle(hdl);
        return -EBADF;
    }

    struct libos_dentry* start = NULL;
    if (*pathname != '/' && get_dirfd_dentry(AT_FDCWD, &start) < 0) {
        put_handle(hdl);
        return -EBADF;
    }

    lock(&g_dcache_lock);
    struct libos_dentry* dent = NULL;
    int ret = path_lookupat(start, pathname,
                            mask & IN_DONTFOLLOW ? LOOKUP_NO_FOLLOW : LOOKUP_FOLLOW, &dent);
    if (ret == 0 && (mask & IN_ONLYDIR)
            && (!dent->inode || !S_ISDIR(dent->inode->type))) {
        ret = -ENOTDIR;
    }
    if (ret == 0) {
        spinlock_lock(&g_inotify_lock);
        struct libos_inotify_watch* existing = NULL;
        for (struct libos_inotify_watch* w = g_inotify_watches; w; w = w->next) {
            if (w->dir_dentry == dent && w->group == hdl) {
                existing = w;
                break;
            }
        }
        if (existing) {
            if (mask & IN_MASK_CREATE) {
                ret = -EEXIST;
            } else {
                if (mask & IN_MASK_ADD)
                    existing->mask |= mask & IN_ALL_EVENTS;
                else
                    existing->mask = mask & IN_ALL_EVENTS;
                /* the kernel's `IN_ADD/MASK_ADD` on a ONESHOT watch keeps it one-shot only if
                 * re-added with ONESHOT */
                existing->oneshot = (mask & IN_ONESHOT) != 0;
                ret = existing->wd;
            }
            spinlock_unlock(&g_inotify_lock);
            goto out_dcache;
        }

        spinlock_lock(&hdl->info.inotify.lock);
        bool full = hdl->info.inotify.watch_count >= INOTIFY_MAX_WATCHES;
        spinlock_unlock(&hdl->info.inotify.lock);
        if (full) {
            ret = -ENOSPC;
            spinlock_unlock(&g_inotify_lock);
            goto out_dcache;
        }

        struct libos_inotify_watch* w = calloc(1, sizeof(*w));
        if (!w) {
            ret = -ENOMEM;
            spinlock_unlock(&g_inotify_lock);
            goto out_dcache;
        }
        get_dentry(dent);
        w->dir_dentry = dent;
        w->group = hdl;
        w->mask = mask & IN_ALL_EVENTS;
        w->oneshot = (mask & IN_ONESHOT) != 0;
        w->wd = alloc_wd_locked(hdl);
        w->next = g_inotify_watches;
        g_inotify_watches = w;
        spinlock_lock(&hdl->info.inotify.lock);
        hdl->info.inotify.watch_count++;
        spinlock_unlock(&hdl->info.inotify.lock);
        spinlock_unlock(&g_inotify_lock);
        ret = w->wd;
    }
out_dcache:
    unlock(&g_dcache_lock);
    if (dent)
        put_dentry(dent);
    if (start)
        put_dentry(start);
    put_handle(hdl);
    return ret;
}

long libos_syscall_inotify_rm_watch(int fd, int wd) {
    struct libos_handle* hdl = get_fd_handle(fd, NULL, NULL);
    if (!hdl)
        return -EINVAL; /* the kernel: `EBADF` was the old answer; current kernels EINVAL */
    if (hdl->type != TYPE_INOTIFY) {
        put_handle(hdl);
        return -EINVAL;
    }

    int ret = -ENOENT;
    bool notify = false;
    spinlock_lock(&g_inotify_lock);
    struct libos_inotify_watch** pp = &g_inotify_watches;
    while (*pp) {
        struct libos_inotify_watch* w = *pp;
        if (w->group == hdl && w->wd == wd) {
            *pp = w->next;
            inotify_queue_event(hdl, wd, IN_IGNORED, 0, NULL, 0, &notify);
            spinlock_lock(&hdl->info.inotify.lock);
            hdl->info.inotify.watch_count--;
            spinlock_unlock(&hdl->info.inotify.lock);
            struct libos_dentry* d = w->dir_dentry;
            free(w);
            spinlock_unlock(&g_inotify_lock);
            put_dentry(d);
            ret = 0;
            break;
        }
        pp = &w->next;
    }
    spinlock_unlock(&g_inotify_lock);

    if (ret == 0)
        inotify_notify_host(hdl);
    put_handle(hdl);
    return ret;
}
